import{z as d,x as l,o as E,c as B,q as o,j as i,D as e,d as t,s as n,S as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"音频语言模型","description":"","frontmatter":{"title":"音频语言模型","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/audio-lm.md","filePath":"llm/audio-lm.md","lastUpdated":1791413859000}'),p={name:"llm/audio-lm.md"};function s(m,a,c,L,u,h){const A=l("Mermaid");return E(),B("div",null,[a[2]||(a[2]=o('<h1 id="音频语言模型" tabindex="-1">音频语言模型 <a class="header-anchor" href="#音频语言模型" aria-label="Permalink to &quot;音频语言模型&quot;">​</a></h1><div class="epigraph"><p>若语音已经是 token，那么「听、说、续写」都可以写成同一个条件：给定过去的符号，预测下一个符号。</p><footer>—— 归纳自 AudioLM / VALL-E / AudioPaLM 一系工作</footer></div><p><a href="/llm/speech-tokenizer">上一课</a>把波形映到离散符号：SoundStream / EnCodec 的 RVQ 服务重建，HuBERT 式单元服务语义；单码本很难同时最优，帧率决定 LLM 序列长度。符号有了。缺口是用语言建模损失在这些符号上训练：可以续写音频、可以条件文本做 TTS、也可以条件音频做 ASR，三者不是一个损失。VALL-E 把 codec 码当「语音文本」来生成；AudioPaLM 把文本能力与音频 token 接到同一解码器；Qwen-Audio 更靠近理解与指令跟随。本课区分这些变体，不重讲 RVQ 与 k-means 怎么离散化。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>经典 ASR 是判别式：最大化 \\(p(y_{\\mathrm{text}}\\mid x_{\\mathrm{audio}})\\)。TTS 是另一套生成式：\\(p(x_{\\mathrm{audio}}\\mid y_{\\mathrm{text}})\\)。对话系统还要 \\(p(y_{\\mathrm{text}}\\mid x_{\\mathrm{audio}}, \\text{context})\\)。三套模型、三套特征、三套对齐，拼接时接口损耗大。Audio LM 的设想是：若存在音频词表 \\(\\mathcal{V}_a\\) 和文本词表 \\(\\mathcal{V}_t\\)，一个模型估计</p> \\[p(z_{t}\\mid z_{\\lt t}),\\qquad z_i\\in\\mathcal{V}_a\\cup\\mathcal{V}_t. \\]<p>条件里既可以有文字也可以有声学码，任务变成前缀不同的同一种解码。困难在于 \\(\\mathcal{V}_a\\) 的帧率高、噪声大，且与 \\(\\mathcal{V}_t\\) 没有天然对齐。硬拼词表会导致文本能力被音频噪声梯度带偏，或音频生成变成含混的嗡嗡。</p><p>另一条路不扩展离散音频词表，只用连续编码器输出当软前缀，LLM 仍只生成文本。Qwen-Audio 更接近这条：理解优先。VALL-E 更接近 codec 上的语言模型：生成优先。AudioPaLM 试图在离散音频与文本之间做联合。</p><p><span class="marginnote">术语翻译：「任务变成前缀不同的同一种解码」就是这个意思——模型本体只有一套「预测下一个符号」，ASR 是「音频码在前、文字在后」的前缀，TTS 是「文字在前、音频码在后」的前缀。就像同一个续写模型，开头塞英文就续英文、塞代码就续代码：任务由前缀决定，不用为每个任务单独建模。</span></p><h3 id="续写、合成与理解不是一个损失" tabindex="-1">续写、合成与理解不是一个损失 <a class="header-anchor" href="#续写、合成与理解不是一个损失" aria-label="Permalink to &quot;续写、合成与理解不是一个损失&quot;">​</a></h3><p>在声学 token 上做 next-token prediction，目标是听感连贯，可以无文本。条件文本再生成声学 token，目标是可懂度和音色。条件声学 token 再生成文本，才是 ASR。同一个 Transformer 可以切三种数据，但采样温度、停词和评估指标完全不同。把「Audio LM」理解成「能听的 GPT」可以，把它理解成「已经解决 ASR」不行。</p><p><span class="marginnote">VALL-E 的冲击是零样本音色克隆：用数秒 EnCodec 码当 prompt，生成同一说话人的新句。能力来自 codec LM，风险也来自它。理解型 Audio LM 不必具备克隆，不应被同一套监管叙事覆盖。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>VALL-E 使用神经编解码器把语音变成多层离散码，再训练自回归（及非自回归 refinement）模型预测这些码。推理时，文本与短音频 prompt 作为条件，模型生成目标句的 codec，再由解码器反变换波形。它是 TTS 侧的 Audio LM，不是转写器。</p><p>AudioPaLM 在 PaLM 上扩展音频 token，使同一解码器能做语音翻译、ASR 与 TTS 等交错任务，展示文本预训练对音频任务的迁移。Qwen-Audio（Chu 等）用大规模音频编码器（以 Whisper 一类结构为起点）连接 Qwen LLM，在多任务音频理解上做指令微调：语音识别只是任务集合之一，还有音频字幕、音景、音乐等。后续 Qwen2-Audio、Qwen2.5-Omni、Qwen3-Omni 把这条理解线推进到流式与全模态，但「Audio LM」这个词在文献里仍常兼指 codec 生成与编码器+LLM 理解。</p>',15)),(E(),i(r,null,{default:e(()=>[n(A,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E9%9F%B3%E9%A2%91%22%5D%20--%3E%20TOK%5B%22%E7%A6%BB%E6%95%A3%20codec%20%E6%88%96%E8%BF%9E%E7%BB%AD%E7%BC%96%E7%A0%81%22%5D%0A%20%20T%5B%22%E6%96%87%E6%9C%AC%22%5D%20--%3E%20EMB%5B%22%E6%96%87%E6%9C%AC%20embedding%22%5D%0A%20%20TOK%20--%3E%20DEC%5B%22%E8%87%AA%E5%9B%9E%E5%BD%92%20LLM%22%5D%0A%20%20EMB%20--%3E%20DEC%0A%20%20DEC%20--%3E%20YT%5B%22%E6%96%87%E6%9C%AC%EF%BC%9AASR%20%2F%20%E5%AF%B9%E8%AF%9D%22%5D%0A%20%20DEC%20--%3E%20YA%5B%22%E9%9F%B3%E9%A2%91%E7%A0%81%EF%BC%9ATTS%20%2F%20%E7%BB%AD%E5%86%99%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<h3 id="条件前缀的写法" tabindex="-1">条件前缀的写法 <a class="header-anchor" href="#条件前缀的写法" aria-label="Permalink to &quot;条件前缀的写法&quot;">​</a></h3><p>理解型：音频特征经 projector 写成一段前缀，随后是用户指令，解码只走文本词表。生成型：文本 token 与 codec 层 token 交错或分阶段解码，停在音频词表。联合型：特殊分隔符切开模态，损失在两种词表上分别计算。Qwen3-ASR 的 LALM 属于理解型加转写头：先形成音频的高层次理解，再生成文字，而不是在 codec 上采样。它与 VALL-E 方向相反，却都依赖「语言模型当解码器」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>自回归 Audio LM 的归纳偏置是：局部声学相关由最近的码解释，长程韵律和句法由更深的注意力解释。文本预训练提供句法与世界知识，对 ASR 的专名、口语修复有帮助，这是 LALM 相对纯 CTC 的理由。但文本先验也会「听成」更常见的词，在噪声里用语言模型盖掉声学——这是另一类错误，不是 WER 表能单独解释的。</p><p><span class="marginnote">常见误区：以为语言模型越强、转写就一定越准。实际有个反面：说话人真说了「Kwok」，语言模型先验会把它「改写」成更常见的「Kwk / 快克」之类——模型用常识覆盖了耳朵。这类错误在清晰音频上不出现、专在噪声与专有名词上冒头，所以纯 WER 榜单看不出模型会不会「不听话」。</span></p><p>连续编码器+LLM 把时间压缩放在编码器（例如 12.5 Hz），LLM 看到的是已经对齐语义的软 token。离散 codec LM 把时间分辨率留得更细，LLM 必须自己学音素结构。计算预算相同时光，理解路线把容量给语言解码，生成路线把容量给码本分层。Qwen 系 Omni 用 Thinker 做理解与文本、Talker 做 codec，是显式拆开这两条损失，避免单一 next-token 目标互撕。</p><p><span class="marginnote">数字实例：同样一秒语音，理解型编码器压成约 12.5 个软 token，codec 路线按 50 Hz × 8 层是 400 个码——后者序列长 30 多倍。省下的上下文就是理解路线敢塞长音频的原因；代价是时间细节在编码器里已经压掉了，想做精确克隆或韵律生成反而不行。</span></p>',7)),(E(),i(r,null,{default:e(()=>[n(A,{id:"mermaid-63",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E4%B8%80%E7%A7%92%E8%AF%AD%E9%9F%B3%22%5D%20--%3E%20UE%5B%22%E7%90%86%E8%A7%A3%E5%9E%8B%EF%BC%9A%E7%BC%96%E7%A0%81%E5%99%A8%E5%8E%8B%E6%88%90%E7%BA%A6%2012%20%E4%B8%AA%E8%BD%AF%20token%22%5D%0A%20%20IN%20--%3E%20CG%5B%22%E7%94%9F%E6%88%90%E5%9E%8B%EF%BC%9Acodec%20%E6%8B%86%E6%88%90%E7%BA%A6%20400%20%E4%B8%AA%E7%A0%81%22%5D%0A%20%20UE%20--%3E%20LLM1%5B%22LLM%20%E5%8F%AA%E8%BE%93%E5%87%BA%E6%96%87%E6%9C%AC%EF%BC%9AASR%E3%80%81%E9%97%AE%E7%AD%94%22%5D%0A%20%20CG%20--%3E%20LLM2%5B%22LM%20%E9%A2%84%E6%B5%8B%E4%B8%8B%E4%B8%80%E4%B8%AA%E7%A0%81%EF%BC%9ATTS%E3%80%81%E7%BB%AD%E5%86%99%22%5D%0A%20%20LLM1%20--%3E%20CAP%5B%22%E5%AE%B9%E9%87%8F%E7%BB%99%E8%AF%AD%E8%A8%80%E8%A7%A3%E7%A0%81%EF%BC%9A%E8%83%BD%E5%90%AC%E6%87%82%E3%80%81%E8%AF%B4%E4%B8%8D%E5%87%BA%22%5D%0A%20%20LLM2%20--%3E%20CAP2%5B%22%E5%AE%B9%E9%87%8F%E7%BB%99%E7%A0%81%E7%BB%93%E6%9E%84%EF%BC%9A%E8%83%BD%E5%85%8B%E9%9A%86%E3%80%81%E4%B8%8D%E5%96%84%E6%8C%87%E4%BB%A4%22%5D%0A%20%20CAP%20--%3E%20OMNI%5B%22Omni%20%E7%B1%BB%E6%8A%8A%E4%B8%A4%E6%9D%A1%E8%B7%AF%E6%8B%86%E6%88%90%20Thinker%20%E4%B8%8E%20Talker%22%5D%0A%20%20CAP2%20--%3E%20OMNI%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<p><span class="marginnote">Qwen-Audio 论文的定位是通用音频理解，而不是神经 TTS。引用时不要把 Qwen-Audio 写成 VALL-E 的开源复现。Qwen2.5-Omni 技术报告（arXiv:2503.20215）才把 Thinker–Talker 的生成侧写全。</span></p><h3 id="评估必须分任务" tabindex="-1">评估必须分任务 <a class="header-anchor" href="#评估必须分任务" aria-label="Permalink to &quot;评估必须分任务&quot;">​</a></h3><p>WER/CER 测转写；MOS 与 speaker similarity 测合成；指令跟随测理解。用 LibriSpeech 分数比较 VALL-E 没有意义，用 MOS 比较 Qwen-Audio 的 ASR 模式也没有意义。AudioPaLM 的论文用多任务表并列，正是因为任务不可比。写系统卡时，应标明这个 Audio LM 实例打开的是哪一张词表。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>长音频使离散码序列极长，纯 codec LM 的上下文先爆。理解型用编码器下采样缓解，却损失时间精度，时间戳要另接对齐模块。流式 TTS 还要因果 codec 与低首包延迟；流式 ASR 要块状编码与稳定的语言模型前缀。两者的工程栈只在「Transformer 解码器」这一层相似。</p><p>数据方面，codec LM 需要大量波形；理解 LM 需要音频–文本–指令三元组。用 TTS 合成数据训理解，会缺真实噪声；用 ASR 数据训 codec LM，会缺韵律多样性。联合训练必须调模态采样比，否则文本或音频一方退化——这正是 Qwen3-Omni 强调「无模态退化」时要打的点。</p><p><span class="marginnote">「音频语言模型」在产品文案里经常等于「能聊天的语音模型」。技术上应还原成：离散或连续音频条件 + 自回归语言头 + 明确的输出词表。缺任何一项，只是管道拼接。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Audio LM 用语言建模目标在音频符号或软音频前缀上训练；任务由条件与输出词表切换，覆盖续写、TTS 与理解。</li><li>VALL-E 是 codec 上的生成式 LM；AudioPaLM 联合文本与音频离散 token；Qwen-Audio 是编码器+LLM 的理解路线。</li><li>理解与生成的损失冲突时，Omni 类架构把 Thinker 与 Talker 拆开，而不是单头硬扛。</li><li>文本先验帮助专名与长上下文，也可能在噪声中覆盖声学证据。</li><li>评估必须按 ASR / TTS / 指令跟随分表，不能用一个 WER 概括 Audio LM。</li><li>出处：Wang 等，VALL-E；Rubenstein 等，AudioPaLM；Chu 等，Qwen-Audio。生成与流式侧见 Qwen2.5-Omni 技术报告（arXiv:2503.20215）与 Qwen3-Omni 技术报告（arXiv:2509.17765）。</li></ul>',9))])}const M=d(p,[["render",s]]);export{_ as __pageData,M as default};
